        return [1]

    result = [1, 3]

    for i in range(2, n + 1):
        if i % 2 == 0:
            result.append(1 + i / 2)
        else:
            # For odd i: tri(i) = tri(i-1) + tri(i-2) + tri(i+1)
            # We need to find tri(i+1) first if i+1 is even
            # tri(i+1) = 1 + (i+1)/2
            tri_next = 1 + (i + 1) / 2
            result.append(result[i - 1] + result[i - 2] + tri_next)

    return result

